using PowerPointIntelligence.Security;
using System;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Threading;
using System.Windows.Forms;
using System.Xml;
using System.Xml.Linq;
using PowerPointIntelligence.AddIn;
using Office=Microsoft.Office.Core;
using PowerPoint=Microsoft.Office.Interop.PowerPoint;
internal sealed class ContextTestForegroundUnavailableException:InvalidOperationException { internal ContextTestForegroundUnavailableException(string message):base(message){} }
internal static class ContextPropertiesOfficeTests
{
    private static int count;
    private static string evidenceDirectory;
    private static int focusCheckpoint;
    private static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL context properties Office: "+name);count++;Console.WriteLine("PASS context properties Office: "+name);}
    private static XmlElement State(dynamic api){string xml=(string)api.GetContextPropertiesState();var d=new XmlDocument {XmlResolver=null};d.LoadXml(xml);return d.DocumentElement;}
    private static XmlElement Wait(dynamic api,PowerPoint.Application app,string kind,bool visible,bool establishFocus=true)
    {
        IntPtr expectedOwner=IntPtr.Zero;
        if(visible){expectedOwner=GetAncestor(new IntPtr(app.ActiveWindow.HWND),2);if(expectedOwner==IntPtr.Zero)throw new InvalidOperationException("The test document window is unavailable.");if(establishFocus&&ContextSelectionBridge.GetForegroundWindow()!=expectedOwner)EnsureTestForeground(app,"selection-"+kind+"-"+(++focusCheckpoint));}
        var watch=System.Diagnostics.Stopwatch.StartNew();XmlElement state=null;do{Application.DoEvents();state=State(api);if(visible&&ContextSelectionBridge.GetForegroundWindow()!=expectedOwner){File.WriteAllText(Path.Combine(evidenceDirectory,"context-properties-focus-lost.xml"),state.OuterXml);throw new ContextTestForegroundUnavailableException("Foreground focus was lost during the "+kind+" panel assertion. This assertion is BLOCKED, not a panel failure or a pass. See context-properties-focus-lost.xml.");}if(state.GetAttribute("refreshes")!="0"&&!String.IsNullOrEmpty(state.GetAttribute("refreshes"))&&state.GetAttribute("visible")== (visible?"true":"false")&&(!visible||state.GetAttribute("kind")==kind&&state.GetAttribute("selectionMatches")=="true"))return state;Thread.Sleep(75);}while(watch.ElapsedMilliseconds<8000);
        File.WriteAllText(Path.Combine(evidenceDirectory,"context-properties-failure.xml"),state.OuterXml);
        throw new Exception("Property-box state did not follow selection. Expected "+kind+" visible="+visible+"; actual="+state.OuterXml+". See context-properties-failure.xml for the actual refresh stage and hidden reason.");
    }
    [DllImport("user32.dll")]private static extern IntPtr GetAncestor(IntPtr window,uint flags);
    [DllImport("user32.dll")]private static extern bool SetForegroundWindow(IntPtr window);
    [DllImport("user32.dll")]private static extern bool IsIconic(IntPtr window);
    [DllImport("user32.dll")]private static extern bool ShowWindowAsync(IntPtr window,int command);
    private static void EnsureTestForeground(PowerPoint.Application app,string checkpoint)
    {
        // Activate selects the Office document; it does not guarantee Windows foreground focus.
        // Request ordinary foreground activation once. Never attach input queues or change OS focus policy.
        var owner=GetAncestor(new IntPtr(app.ActiveWindow.HWND),2);if(owner==IntPtr.Zero)throw new InvalidOperationException("The test document's top-level window could not be resolved.");
        if(IsIconic(owner))ShowWindowAsync(owner,9);
        Console.WriteLine("STEP foreground prerequisite: activate the test PowerPoint window if Windows refuses the normal focus request.");
        var watch=System.Diagnostics.Stopwatch.StartNew();var result=ContextForegroundPolicy.Establish(()=>ContextSelectionBridge.GetForegroundWindow()==owner,()=>SetForegroundWindow(owner),()=>{Application.DoEvents();Thread.Sleep(75);},()=>watch.ElapsedMilliseconds,15000);
        bool promptShown=false,userStarted=false,userRequestAccepted=false;
        if(!result.Verified){
            promptShown=true;Console.WriteLine("STEP user focus handoff: click Start test in the PowerPoint test ready window (Alt+Tab if needed). It cancels after 60 seconds.");
            using(var prompt=new ContextForegroundPrompt(()=>SetForegroundWindow(owner))){prompt.ShowDialog();userStarted=prompt.StartRequested;userRequestAccepted=prompt.RequestAccepted;}
            if(userStarted){watch.Restart();while(ContextSelectionBridge.GetForegroundWindow()!=owner&&watch.ElapsedMilliseconds<15000){Application.DoEvents();Thread.Sleep(75);}result.Verified=ContextSelectionBridge.GetForegroundWindow()==owner;}
        }
        var doc=new XmlDocument();var root=doc.CreateElement("testForeground");doc.AppendChild(root);root.SetAttribute("checkpoint",checkpoint);root.SetAttribute("initiallyForeground",result.InitiallyForeground?"true":"false");root.SetAttribute("requestAccepted",result.RequestAccepted?"true":"false");root.SetAttribute("verified",result.Verified?"true":"false");root.SetAttribute("promptShown",promptShown?"true":"false");root.SetAttribute("userStarted",userStarted?"true":"false");root.SetAttribute("userRequestAccepted",userRequestAccepted?"true":"false");File.WriteAllText(Path.Combine(evidenceDirectory,"context-foreground-"+checkpoint+".xml"),doc.OuterXml);
        if(!result.Verified)throw new ContextTestForegroundUnavailableException("Windows did not give the owned test PowerPoint window foreground focus. No panel-appearance assertion was attempted. See context-foreground-"+checkpoint+".xml; the Start test handoff was cancelled, timed out or still could not establish focus. No Windows focus/security policy was changed.");
        Console.WriteLine("PASS foreground prerequisite: "+checkpoint);
    }
    private static void ProbeSelectedText(PowerPoint.Application app,string checkpoint="text")
    {
        var doc=new XmlDocument();var root=doc.CreateElement("selectionProbe");doc.AppendChild(root);
        try{var snapshot=ContextSelectionBridge.Capture(app);if(snapshot==null)throw new InvalidOperationException("No supported selection was resolved.");root.SetAttribute("status","captured");root.SetAttribute("kind",snapshot.Snapshot.Kind.ToString());root.SetAttribute("font",snapshot.Snapshot.CanFont?"true":"false");root.SetAttribute("powerpointForeground",ContextSelectionBridge.GetForegroundWindow()==snapshot.Owner?"true":"false");}
        catch(Exception error){root.SetAttribute("status","failed");root.SetAttribute("stage",ContextSelectionBridge.InspectionStage??"unknown");root.SetAttribute("exception",error.GetType().Name);root.SetAttribute("hresult","0x"+error.HResult.ToString("X8"));throw new InvalidOperationException("Selection inspection failed at "+ContextSelectionBridge.InspectionStage+" ("+root.GetAttribute("hresult")+"). See context-selection-probe-"+checkpoint+".xml.",error);}
        finally{File.WriteAllText(Path.Combine(evidenceDirectory,"context-selection-probe-"+checkpoint+".xml"),doc.OuterXml);}
    }
    internal static void Run(PowerPoint.Application app,string output)
    {output=PathPolicy.TestPath(output);
        Directory.CreateDirectory(output);evidenceDirectory=output;focusCheckpoint=0;count=0;var connections=app.COMAddIns.Cast<Office.COMAddIn>().Where(a=>(a.ProgId+" "+a.Description).Contains("PowerPointIntelligence")||(a.ProgId+" "+a.Description).Contains("PowerPoint Intelligence")).ToArray();if(connections.Length!=1||!connections[0].Connect)throw new InvalidOperationException("Install/connect the current PowerPoint Intelligence add-in before contextual UI validation.");dynamic api=connections[0].Object;string build=(string)api.GetBuildInfo();if(!build.StartsWith(DemoRibbon.BuildMarker+";",StringComparison.Ordinal))throw new InvalidOperationException("Installed add-in is stale. Install the current source before testing its automatic property box.");
        PowerPoint.Presentation deck=null;string file=Path.Combine(PathPolicy.TestPath(output),"context-properties-native.pptx");try{
            deck=app.Presentations.Add(Office.MsoTriState.msoTrue);deck.PageSetup.SlideWidth=960;deck.PageSetup.SlideHeight=540;var slide=deck.Slides.Add(1,PowerPoint.PpSlideLayout.ppLayoutBlank);deck.Windows[1].ViewType=PowerPoint.PpViewType.ppViewNormal;deck.Windows[1].Activate();EnsureTestForeground(app,"initial");slide.Select();app.ActiveWindow.Selection.Unselect();Wait(api,app,"None",false);Check(true,"no selection hides property box");
            var text=TextShapeElements.Insert(app,"textbox");text.TextFrame.TextRange.Text="Native property box";text.Select();ProbeSelectedText(app);EnsureTestForeground(app,"text-baseline");var foreground=ContextSelectionBridge.GetForegroundWindow();var info=Wait(api,app,"Text",true,false);Check(ContextSelectionBridge.GetForegroundWindow()==foreground,"automatic property box does not steal foreground focus");Check(info.GetAttribute("font")=="true"&&info.GetAttribute("fill")=="true","managed text exposes applicable properties");string textKey=ContextSelectionBridge.Key(app);int textId=text.Id;
            ContextFormatting.ApplyFont(app,"Arial",22,true,null);NativeFormatting.Text(app,"center");NativeFormatting.Text(app,"middle");Check(text.TextFrame.TextRange.Font.Size==22&&text.TextFrame.TextRange.Font.Bold==Office.MsoTriState.msoTrue,"font edits apply to native field");
            var rounded=TextShapeElements.Insert(app,"roundedRectangle");rounded.TextFrame.TextRange.Text="Rounded";rounded.Select();Wait(api,app,"Text",true);bool stale=false;int original=text.Fill.ForeColor.RGB;try{ContextSelectionBridge.ApplyColor(app,textKey,"fill",0x123456);}catch(InvalidOperationException){stale=true;}Check(stale&&text.Fill.ForeColor.RGB==original,"stale target is rejected before color mutation");
            string sourceSettings=TextShapeCodec.Encode(TextShapeElements.Read(rounded));rounded.Select();var grid=ProcessFlowTools.Create(app);grid.Select();Wait(api,app,"ProcessGrid",true);Check(true,"process grid opens contextual controls");
            var cells=slide.Shapes.Cast<PowerPoint.Shape>().Where(s=>s.Tags[ProcessFlowTools.GridTag]==grid.Tags[ProcessFlowTools.GridTag]).ToArray();Check(cells.Length==6&&cells.All(s=>!TextShapeElements.Read(s).AutoFit),"styled grid creates six readable canonical cell settings");Check(TextShapeCodec.Encode(TextShapeElements.Read(rounded))==sourceSettings,"grid style transfer preserves source element metadata");
            var indicator=IndicatorElements.Insert(app,"harvey");indicator.Select();info=Wait(api,app,"Indicator",true);Check(info.GetAttribute("font")=="false"&&info.GetAttribute("fill")=="true","indicator exposes canonical colors without misleading font controls");ContextSelectionBridge.ApplyColor(app,ContextSelectionBridge.Key(app),"fill",0xA0B0C0);indicator=app.ActiveWindow.Selection.ShapeRange[1];Check(IndicatorElements.Read(indicator).FilledColor==0xA0B0C0,"indicator color updates persisted canonical state");
            var table=slide.Shapes.AddTable(2,2,80,330,300,110);table.Table.Cell(1,1).Shape.TextFrame.TextRange.Text="One";table.Table.Cell(2,2).Shape.TextFrame.TextRange.Text="Two";table.Select();ProbeSelectedText(app,"table");info=Wait(api,app,"Table",true);Check(info.GetAttribute("font")=="true","native table receives editable font properties");ContextFormatting.ApplyFont(app,null,17,null,null);Check(table.Table.Cell(1,1).Shape.TextFrame.TextRange.Font.Size==17&&table.Table.Cell(2,2).Shape.TextFrame.TextRange.Font.Size==17,"table font scope covers native cells");table.Table.Cell(1,1).Shape.TextFrame.TextRange.Select();string one=ContextSelectionBridge.Key(app);table.Table.Cell(2,2).Shape.TextFrame.TextRange.Select();Check(ContextSelectionBridge.Key(app)!=one,"different table text cells have distinct selection identities");
            var chart=slide.Shapes.AddChart2(-1,Office.XlChartType.xlColumnClustered,440,260,400,230,false);chart.Select();ProbeSelectedText(app,"chart");info=Wait(api,app,"Chart",true);Check(info.GetAttribute("font")=="true","native chart receives chart-specific context");
            var connector=UniversalConnectors.Create(app,new ConnectorSpec {Begin=new ConnectorEndpoint {ShapeId=text.Id,Site=1},End=new ConnectorEndpoint {ShapeId=rounded.Id,Site=1}});connector.Select();Wait(api,app,"Connector",true);Check(true,"universal connector receives its own controls");var connectorState=UniversalConnectors.Read(connector);Check(connectorState.Begin.ShapeId==text.Id&&connectorState.End.ShapeId==rounded.Id,"context connector retains native endpoint bindings");File.WriteAllText(Path.Combine(output,"context-connector-geometry.xml"),new XElement("connectorGeometry",new XAttribute("rotation",connector.Rotation),new XAttribute("width",connector.Width),new XAttribute("height",connector.Height),new XAttribute("flipH",connector.HorizontalFlip),new XAttribute("flipV",connector.VerticalFlip)).ToString());
            var rotatedFree=UniversalConnectors.Create(app,new ConnectorSpec {Route="straight",Begin=new ConnectorEndpoint {Kind="free",X=120,Y=120},End=new ConnectorEndpoint {Kind="free",X=300,Y=160}});int rotatedFreeId=rotatedFree.Id;string beforeRotationXml=ConnectorCodec.Encode(UniversalConnectors.Read(rotatedFree));rotatedFree.Rotation+=90;Check(ConnectorCodec.Encode(UniversalConnectors.Read(rotatedFree))==beforeRotationXml,"native rotation preserves attached connector metadata before reflow");float retainedRotation=rotatedFree.Rotation;UniversalConnectors.Reflow(app);var rotatedSpec=UniversalConnectors.Read(rotatedFree);Check(Math.Abs(rotatedSpec.Begin.X-230)<.2&&Math.Abs(rotatedSpec.Begin.Y-50)<.2&&Math.Abs(rotatedSpec.End.X-190)<.2&&Math.Abs(rotatedSpec.End.Y-230)<.2,"native rotated connector endpoints are captured in slide coordinates");Check(Math.Abs(rotatedFree.Rotation-retainedRotation)<.01,"connector capture preserves native rotation");string rotatedXml=ConnectorCodec.Encode(rotatedSpec);
            slide.Shapes.Range(new object[]{text.Name,rounded.Name}).Select();Wait(api,app,"Text",true);Check(true,"multi-selection shares property box");
            deck.SaveAs(file,PowerPoint.PpSaveAsFileType.ppSaveAsOpenXMLPresentation,Office.MsoTriState.msoFalse);deck.Close();deck=null;Wait(api,app,"None",false);Check(true,"closing document hides the property box");deck=app.Presentations.Open(file,Office.MsoTriState.msoFalse,Office.MsoTriState.msoFalse,Office.MsoTriState.msoTrue);deck.Windows[1].Activate();deck.Windows[1].ViewType=PowerPoint.PpViewType.ppViewNormal;EnsureTestForeground(app,"reopen");slide=deck.Slides[1];text=slide.Shapes.Cast<PowerPoint.Shape>().Single(s=>s.Id==textId);text.Select();Wait(api,app,"Text",true);Check(text.TextFrame.TextRange.Font.Size==22,"native formatting and contextual selection survive save reopen");var restoredConnector=slide.Shapes.Cast<PowerPoint.Shape>().Single(s=>s.Id==rotatedFreeId);Check(ConnectorCodec.Encode(UniversalConnectors.Read(restoredConnector))==rotatedXml&&Math.Abs(restoredConnector.Rotation-retainedRotation)<.01,"rotated native connector geometry and metadata survive save reopen");
            File.WriteAllText(Path.Combine(output,"context-properties-state.xml"),State(api).OuterXml);Console.WriteLine("CONTEXT "+count+" native assertions passed; Office="+app.Version+"; process="+(Environment.Is64BitProcess?"x64":"x86")+". Color-picker visuals, every chart family and per-monitor DPI still need manual coverage.");
        }finally{if(deck!=null){deck.Saved=Office.MsoTriState.msoTrue;deck.Close();}}
    }
}
